CREATE OR REPLACE FUNCTION ops.validate_export_run() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM core.workspace w WHERE w.id=NEW.workspace_id AND w.owner_user_id=NEW.requested_by_user_id) OR NOT EXISTS(SELECT 1 FROM core.command_receipt c WHERE c.workspace_id=NEW.workspace_id AND c.id=NEW.command_receipt_id AND c.command_type=CASE WHEN NEW.export_kind='workspace_bundle' THEN 'portability.export' ELSE 'reporting.export_csv' END AND c.state='completed' AND c.result_json->>'exportRunId'=NEW.id::text) THEN RAISE EXCEPTION 'export provenance needs owned completed command' USING ERRCODE='23514';END IF;
 IF NEW.export_kind='workspace_bundle' AND (NEW.bundle_json IS NULL OR NEW.expires_at IS NULL OR NEW.expires_at>NEW.generated_at+interval '24 hours' OR NEW.checksum_sha256 IS DISTINCT FROM NEW.bundle_json->>'checksumSha256' OR encode(sha256(convert_to(ops.canonical_json(NEW.bundle_json-'checksumSha256'),'UTF8')),'hex')<>NEW.checksum_sha256) THEN RAISE EXCEPTION 'bounded workspace export invalid';END IF;RETURN NULL;END $$;
CREATE OR REPLACE FUNCTION ops.guard_export_run() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' THEN IF current_user='lifecycle_operator' AND ops.purge_scope_allowed(OLD.workspace_id) THEN RETURN OLD;END IF;IF OLD.created_at>=transaction_timestamp()-interval '30 days' THEN RAISE EXCEPTION 'export provenance retains thirty days';END IF;RETURN OLD;END IF;
 IF OLD.export_kind='workspace_bundle' AND OLD.expires_at<clock_timestamp() AND NEW.bundle_json IS NULL AND NEW.state='expired' AND (to_jsonb(NEW)-ARRAY['bundle_json','state'])=(to_jsonb(OLD)-ARRAY['bundle_json','state']) THEN RETURN NEW;END IF;RAISE EXCEPTION 'export provenance immutable' USING ERRCODE='23514';END $$;
CREATE POLICY h_expired_exports ON ops.export_run TO migration_owner USING(export_kind='workspace_bundle' AND expires_at<clock_timestamp()) WITH CHECK(export_kind='workspace_bundle' AND expires_at<clock_timestamp());
CREATE POLICY h_expired_restores ON ops.restore_run TO migration_owner USING(expires_at<clock_timestamp() AND state<>'applying') WITH CHECK(expires_at<clock_timestamp() AND state<>'applying');
CREATE POLICY h_expired_maps ON ops.restore_id_map TO migration_owner USING(EXISTS(SELECT 1 FROM ops.restore_run r WHERE r.workspace_id=workspace_id AND r.id=restore_run_id AND r.expires_at<clock_timestamp() AND r.state<>'applying'));
CREATE FUNCTION ops.expire_portable_artifacts() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE n integer;BEGIN
 WITH expired AS(SELECT id FROM ops.export_run WHERE export_kind='workspace_bundle' AND state='completed' AND expires_at<clock_timestamp() ORDER BY expires_at LIMIT 100 FOR UPDATE SKIP LOCKED) UPDATE ops.export_run SET bundle_json=NULL,state='expired' WHERE id IN(SELECT id FROM expired);GET DIAGNOSTICS n=ROW_COUNT;
 DELETE FROM ops.restore_id_map WHERE restore_run_id IN(SELECT id FROM ops.restore_run WHERE expires_at<clock_timestamp() AND state<>'applying' ORDER BY expires_at LIMIT 100);
 UPDATE ops.restore_run SET bundle_json='{}'::jsonb,recovery_json=NULL WHERE id IN(SELECT id FROM ops.restore_run WHERE expires_at<clock_timestamp() AND state<>'applying' AND (bundle_json<>'{}'::jsonb OR recovery_json IS NOT NULL) ORDER BY expires_at LIMIT 100 FOR UPDATE SKIP LOCKED);RETURN n;END $$;
REVOKE ALL ON FUNCTION ops.expire_portable_artifacts() FROM PUBLIC;GRANT EXECUTE ON FUNCTION ops.expire_portable_artifacts() TO worker_domain;
